    [Handler("AMessage", "A Message", typeof(SAMessage), "Anonymous")]
    [ManualQuestion("What was the received message?")]
    private IEnumerator<SouvenirInstruction> ProcessAMessage(ModuleData module)
    {
        static IEnumerable<string> AnswerGenerator()
        {
            while (true)
            {
                var m = Random.Range(0, _aMessage_message.Length - 5);
                yield return Random.Range(0, 2) == 0 ? _aMessage_message.Substring(m, 5) : new string(_aMessage_message.Substring(m, 5).Reverse().ToArray());
            }
        }

        yield return WaitForSolve;
        var comp = GetComponent(module, "AMessageScriptRedone");
        var data = GetArrayField<int>(comp, "SequenceNumbers").Get(expectedLength: 5, validator: v => v is < 0 or > 31 ? "Out of range [0, 31]" : null);
        var sol = GetArrayField<int>(comp, "RealNumbers").Get(expectedLength: 5, validator: v => v is < 0 or > 31 ? "Out of range [0, 31]" : null);
        static string convert(int[] nums) => new(nums.Select(i => (char) ('\ue900' + i)).ToArray());
        yield return question(SAMessage.AMessage).Answers(convert(data), preferredWrong: [convert(sol)], answerGenerator: AnswerGenerator());
    }
